using System.Collections.Generic;
using UnityEngine;
namespace Blocklands {
 public enum FestivalKind { Coaster, Dance, Memory, Dig, Footprints, Flight, Sailing }
 public partial class FestivalStation:MonoBehaviour {
  Sandbox game;RoyalArt art;FestivalKind kind;readonly List<Transform> targets=new List<Transform>();readonly List<Transform> dancers=new List<Transform>();Transform cart;Vector3[] track;Vector3 entry;int progress;float elapsed,cooldown;bool paid;AudioSource sound;AudioClip note;Font font;
  public bool Running {get;private set;}public bool Won {get;private set;}public string Title {get;private set;}public Vector3 Centre=>transform.position;public int Progress=>progress;public bool LocksPlayer=>Running&&(kind==FestivalKind.Coaster||kind==FestivalKind.Dance||kind==FestivalKind.Memory);public FestivalKind Kind=>kind;public float Elapsed=>elapsed;public int ExpectedDirection=>PolishExpectedDirection;
  public Vector3 Target(int i)=>targets[i].position;
  public void Initialize(Sandbox owner,FestivalKind mode,string title,Vector3 centre){game=owner;kind=mode;Title=title;transform.position=centre;art=gameObject.AddComponent<RoyalArt>();font=Resources.Load<Font>("NotoSansCJKsc-Regular");art.Piece("活动路牌",new Vector3(0,1.8f,-1),new Vector3(3.4f,.8f,.15f),new Color(.15f,.32f,.4f));Label(title+"\n靠近按 G",new Vector3(0,1.83f,-1.1f));
   sound=gameObject.AddComponent<AudioSource>();sound.playOnAwake=false;sound.volume=.15f;var data=new float[4410];for(int i=0;i<data.Length;i++)data[i]=Mathf.Sin(i*440*Mathf.PI*2/44100)*(.2f*(1-i/(float)data.Length));note=AudioClip.Create("活动提示音",data.Length,1,44100,false);note.SetData(data,0);
   if(kind==FestivalKind.Coaster)BuildCoaster();else if(kind==FestivalKind.Dance||kind==FestivalKind.Memory){art.Piece("彩灯舞台",new Vector3(0,-.15f,2),new Vector3(7,.3f,6),new Color(.27f,.15f,.38f),PrimitiveType.Cube,true);for(int i=0;i<4;i++){var pad=art.Piece("节奏灯 "+i,new Vector3((i-1.5f)*1.3f,.1f,3),new Vector3(1,.15f,1),Color.HSVToRGB(i*.22f,.6f,.9f));targets.Add(pad);}if(kind==FestivalKind.Dance&&centre.y<0)for(int i=0;i<4;i++){var actor=new GameObject(i<2?"友好猪灵舞伴":"友好羊灵舞伴");actor.transform.SetParent(transform,false);actor.transform.localPosition=new Vector3((i-1.5f)*1.5f,.1f,3.5f);var spirit=actor.AddComponent<CavernSpirit>();spirit.Initialize(game,i<2);spirit.Friendly=true;dancers.Add(actor.transform);}}
   else {int count=kind==FestivalKind.Dig?3:6;for(int i=0;i<count;i++){float angle=i*Mathf.PI*2/count;Vector3 p=centre+new Vector3(Mathf.Sin(angle)*5,kind==FestivalKind.Flight?3+Mathf.Sin(angle)*2:0,Mathf.Cos(angle)*5+6);if(centre.y>=0&&kind!=FestivalKind.Flight)p=FloorAt(p)+Vector3.up*.15f;p=ClearTarget(p);var target=art.Piece(kind==FestivalKind.Footprints?"神秘大脚印":"探索目标 "+(i+1),p-centre,kind==FestivalKind.Footprints?new Vector3(1.1f,.07f,2):kind==FestivalKind.Dig?Vector3.one*.9f:Vector3.one*.65f,kind==FestivalKind.Footprints?new Color(.15f,.11f,.23f):Color.HSVToRGB(i*.13f,.6f,1));targets.Add(target);if(kind==FestivalKind.Flight){target.GetComponent<Renderer>().enabled=false;var ring=target.gameObject.AddComponent<RoyalArt>();for(int k=0;k<16;k++){float a=k*Mathf.PI/8;ring.Piece("飞行光环",new Vector3(Mathf.Cos(a)*1.7f,Mathf.Sin(a)*1.7f,0),Vector3.one*.3f,new Color(1,.8f,.25f),PrimitiveType.Sphere);}}if(kind==FestivalKind.Footprints)for(int toe=0;toe<3;toe++)art.Piece("脚趾印",p-centre+new Vector3((toe-1)*.32f,0,1.15f),new Vector3(.27f,.07f,.45f),new Color(.15f,.11f,.23f));Label((i+1).ToString(),p-centre+Vector3.up*1.25f);}}
  }
  Vector3 FloorAt(Vector3 p){int x=Mathf.Clamp((int)p.x,1,62),z=Mathf.Clamp((int)p.z,1,62);for(int y=55;y>=0;y--)if(Blocks.Solid(game.World.Get(new Vector3Int(x,y,z))))return new Vector3(x+.5f,y+1,z+.5f);return p;}
  Vector3 ClearTarget(Vector3 p){if(kind==FestivalKind.Flight){p.y=Mathf.Max(p.y,FloorAt(p).y+3);return p;}if(p.y>=0||kind==FestivalKind.Sailing)return p;for(int radius=0;radius<=10;radius++)for(int dx=-radius;dx<=radius;dx++)for(int dz=-radius;dz<=radius;dz++){var q=p+new Vector3(dx,0,dz);var cell=Vector3Int.FloorToInt(q);if(!VoxelWorld.InBounds(cell)||game.World.Get(cell)!=Block.Air||game.World.Get(cell+Vector3Int.up)!=Block.Air)continue;bool distinct=true;foreach(var other in targets)if(Vector3.Distance(other.position,q)<2)distinct=false;if(distinct)return q;}return p;}
  void Label(string text,Vector3 local){var o=new GameObject("提示").transform;o.SetParent(transform,false);o.localPosition=local;var t=o.gameObject.AddComponent<TextMesh>();t.font=font;o.GetComponent<Renderer>().sharedMaterial=font.material;t.text=text;t.characterSize=.085f;t.fontSize=36;t.anchor=TextAnchor.MiddleCenter;t.color=Color.white;}
  void Beam(string title,Vector3 a,Vector3 b,float width,Color color){var p=art.Piece(title,(a+b)*.5f-Centre,new Vector3(width,width,Vector3.Distance(a,b)),color);p.rotation=Quaternion.LookRotation(b-a);}
  public bool Interact(){if(!game.FestivalInputAvailable)return false;if(!Running){StartGame();return Running;}if(LocksPlayer){Cancel();return true;}
   if(kind==FestivalKind.Dig&&progress<targets.Count&&Vector3.Distance(game.Player.transform.position,targets[progress].position)<=3){targets[progress].localScale*=.75f;progress++;PolishCorrect();Tone();if(progress==targets.Count)Finish();return true;}if(Vector3.Distance(game.Player.transform.position,Centre)<=4){Cancel();return true;}return false;}
  public void StartGame(){if(Running||!game.FestivalInputAvailable||game.DepthBoatRiding&&kind!=FestivalKind.Sailing||Vector3.Distance(game.Player.transform.position,Centre)>5)return;foreach(var s in game.FestivalStations)if(s!=null&&s!=this&&s.Running)s.Cancel();entry=game.Player.transform.position;Running=true;Won=false;elapsed=0;progress=0;cooldown=0;foreach(var t in targets)t.gameObject.SetActive(true);if(LocksPlayer)game.Player.HomeRest(true);if(kind==FestivalKind.Coaster)BeginCoasterRide();BeginPolish();if(kind==FestivalKind.Flight)game.Player.SetFlying(true);game.Notice=Title+"开始！";}
  void Tone(){sound.pitch=1+progress*.07f;sound.PlayOneShot(note);}
  // KeyDown already represents a discrete tap. A hidden cooldown discarded quick,
  // correct answers (including the last one) while the UI showed the next step.
  public void Direction(int direction){if(!Running||!game.FestivalInputAvailable||direction<0||direction>3||(kind!=FestivalKind.Dance&&kind!=FestivalKind.Memory)||kind==FestivalKind.Memory&&elapsed<5)return;if(direction!=ExpectedDirection){PolishWrong();Tone();return;}progress++;PolishCorrect();Tone();if(progress>=(kind==FestivalKind.Memory?5:8))Finish();}
  public void RideBonus(){if(Running&&game.FestivalInputAvailable&&kind==FestivalKind.Coaster&&elapsed>=cooldown){progress++;cooldown=elapsed+4;Tone();}}
  public void Tick(float dt){if(!Running||!game.FestivalInputAvailable)return;elapsed+=Mathf.Max(0,dt);if(kind==FestivalKind.Coaster){TickCoaster(dt);return;}if(elapsed>=90){Cancel();game.Notice="时间到了，可以回活动牌重新挑战。";return;}
   foreach(var d in dancers){var spirit=d.GetComponent<CavernSpirit>();spirit.Dancing=true;d.localRotation=Quaternion.Euler(0,180+Mathf.Sin(elapsed*4+d.localPosition.x)*25,0);foreach(Transform part in d)if(part.name=="arm")part.localRotation=Quaternion.Euler(Mathf.Sin(elapsed*6)*45,0,0);}
   if(kind==FestivalKind.Flight||kind==FestivalKind.Footprints||kind==FestivalKind.Sailing){if(progress<targets.Count&&Vector3.Distance(game.Player.transform.position,targets[progress].position)<(kind==FestivalKind.Sailing?3:2.6f)){targets[progress].gameObject.SetActive(false);progress++;PolishCorrect();Tone();if(progress==targets.Count)Finish();}}
   TickPolish();}
  void Stop(){bool restorePose=LocksPlayer;Running=false;StopPolish();foreach(var d in dancers)if(d!=null)d.GetComponent<CavernSpirit>().Dancing=false;if(restorePose)game.Player.HomeRest(false);if(kind==FestivalKind.Coaster)EndCoasterRide(true);}
  public void Cancel(){if(!Running)return;Stop();game.Notice="已结束"+Title+"，可随时再来。";}
  public int CoinReward=>kind==FestivalKind.Coaster?80:kind==FestivalKind.Dance?45:kind==FestivalKind.Memory?35:kind==FestivalKind.Dig?30:kind==FestivalKind.Flight?60:kind==FestivalKind.Sailing?55:40;
  void Finish(){if(!Running)return;CompletePolish();Stop();Won=true;bool firstWin=!paid;int cookiesBefore=game.Inventory[(int)Block.Cookie];if(firstWin){paid=true;game.Inventory[(int)Block.Cookie]=Mathf.Min(9999,cookiesBefore+3);}int earned=game.EarnActivityCoins(CoinReward,Title);if(earned==0&&firstWin){game.Inventory[(int)Block.Cookie]=cookiesBefore;paid=false;}if(earned>0)game.Notice=Title+"完成！获得"+earned+"元"+(firstWin?"和3块饼干。":"。")+" 靠近活动牌按G可重玩。";if(kind==FestivalKind.Footprints&&transform.Find("足迹守护者笑脸")==null){art.Piece("足迹守护者笑脸",new Vector3(0,2,6),Vector3.one*1.6f,new Color(.4f,.2f,.6f),PrimitiveType.Sphere);foreach(float x in new[]{-.35f,.35f})art.Piece("亮眼睛",new Vector3(x,2.3f,5.2f),Vector3.one*.2f,Color.yellow);art.Piece("神秘微笑",new Vector3(0,1.65f,5.2f),new Vector3(.6f,.08f,.1f),Color.yellow);}}
  void Update(){if(game==null||!game.FestivalInputAvailable)return;Tick(Time.deltaTime);if(Running&&!game.IsSmoke){if(Input.GetKeyDown(KeyCode.LeftArrow))Direction(0);else if(Input.GetKeyDown(KeyCode.UpArrow))Direction(1);else if(Input.GetKeyDown(KeyCode.RightArrow))Direction(2);else if(Input.GetKeyDown(KeyCode.DownArrow))Direction(3);if(Input.GetKeyDown(KeyCode.Space))RideBonus();}}
  void OnGUI(){if(game==null||game.Paused||game.PhoneOpen||game.PalaceConsoleOpen||!Running&&Vector3.Distance(game.Player.transform.position,Centre)>8)return;var s=new GUIStyle(GUI.skin.label){font=font,fontSize=17,wordWrap=true};s.normal.textColor=Color.white;string hint=!Running?(Won?"已完成 · G再玩一次":"靠近活动牌按G开始"):kind==FestivalKind.Coaster?CoasterStatus:kind==FestivalKind.Dance?"跟着节拍按 "+new[]{"←","↑","→","↓"}[ExpectedDirection]+" · "+progress+"/8 · G结束":kind==FestivalKind.Memory?(elapsed<5?"记住："+PolishMemoryPreview:"按记住的方向键 · "+progress+"/5 · G结束"):kind==FestivalKind.Dig?"按编号走到3处遗迹旁，G挖掘 · "+progress+"/3":"按编号接近发光目标 · "+progress+"/6 · "+Mathf.CeilToInt(90-elapsed)+"秒";GUI.Box(new Rect(20,295,520,82),"");GUI.Label(new Rect(32,301,495,74),Title+"\n"+hint,s);DrawPolishOverlay();}
  void OnDestroy(){if(kind==FestivalKind.Coaster){EndCoasterRide(false);DisposeCoasterMeshes();}if(note!=null)Destroy(note);}
 }
}
